class Note {
	constructor(r, a, i, c) {
		this.r = r;
		this.a = a;
		this.i = i;
		this.c = c;
		this.al = 60;
	}
	show() {
		let x = platter.height / 2 + this.r * sin(this.a);
		let y = platter.height / 2 - this.r * cos(this.a);
		platter.strokeWeight(height / 1200);
		this.c.setAlpha(255)
		platter.stroke(this.c);
		this.c.setAlpha(this.al);
		platter.fill(this.c);
		platter.ellipse(x, y, platter.height / 200);
	}
}

// === Tab: mySketch ===
// For the #WCCChallenge, theme: "music visualization."
// This is the G major Prelude from J.S. Bach's Cello Suite #1.
// I did a 2D version of this a few years ago, and decided
// to refactor it in 3D for this week's challenge!

let notes;
let piece = [];
let osc, env1, env2;
let rows;
let interval;
let index = 0;
let angle = 0;
let zoom = 1;
let tzoom = 2;
let playing = false;
let divider = 10;
let fmult = 1;
let platter;
let tilt;
let startC, endC;
let timer = 0;

function preload() {
	notes = loadTable('https://openprocessing.org/sketch/2731036/files/Cello Notes - Sheet1.csv');
}

function setup() {
	createCanvas(windowWidth - 1, windowHeight - 1, WEBGL);
	platter = createGraphics(height, height);
	startC = color('rgb(0,120,180)');
	endC = color('rgb(120,180,0)');
	osc = new p5.Oscillator('triangle');
	osc.start();
	osc.amp(0);
	env1 = new p5.Envelope(0.02, 0.3, 0.1, 0.0);
	env2 = new p5.Envelope(0.02, 0.1, 1.5, 0.0);
	rows = notes.getRowCount() - 1;
	interval = TAU / rows;
	for (let i = 0; i < rows; i++) {
		let r = map(notes.get(i, 0), 36, 67, platter.height / 5.5, platter.height / 2.1)
		angle += interval;
		let c = lerpColor(startC, endC, map(r, platter.height / 5.5, platter.height / 2, 0, 1, true));
		piece.push(new Note(r, angle, i, c));
	}
	angle = 0;
	tilt = createVector(0, 0, 0);
	ttilt = createVector(QUARTER_PI, 0, 0);
	drawNotes();
	imageMode(CENTER);
}

function draw() {
	if (playing) timer += 1;
	background(0);
	setScene();
	image(platter, 0, 0);
	drawCursor();
	playNote();
}

function setScene() {
	zoom = lerp(zoom, tzoom, 0.1);
	scale(zoom);
	if (playing) angle += interval / divider;
	tzoom = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 0.5, 2);
	tilt.lerp(ttilt, 0.1);
	rotateX(tilt.x);
	rotateZ(tilt.z - angle);
	ttilt.x = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, PI, -PI);
	ttilt.z = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -PI, PI);
}

function playNote() {
	if (playing && timer % divider == 0) {
		let freq = midiToFreq(notes.get(index, 0));
		freq *= fmult;
		osc.freq(freq);
		osc.pan(map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),0,width,-1,1))
		if (index < rows - 1) env1.play(osc);
		else env2.play(osc); // draw out last note
		highlightNote();
		index += 1;
		if (index > 616) { // ritardando at end
			timer = 0;
			divider = 11;
		}
		if (index > rows) {
			index = rows;
			playing = false;
		}
	}
}

function drawNotes() {
	platter.background(0);
	platter.noFill();
	platter.stroke(endC);
	platter.ellipse(platter.width / 2, platter.height / 2, platter.height);
	for (let n of piece) {
		n.show();
	}
}

function highlightNote() {
	if (index < piece.length) {
		piece[index].al = 255;
		piece[index].show();
	}
}

function drawCursor() {
	let i = index;
	if (index > rows - 1) i = rows - 1;
	var r = piece[i].r;
	var c = piece[i].c;
	push()
	rotateZ(angle)
	rotateX(HALF_PI);
	noStroke();
	c.setAlpha(100);
	fill(c);
	push();
	rotateY(-HALF_PI);
	var x = (height / 2 - height / 6);
	translate(x, 0, 0);
	box(x, height / 202, height / 480);
	pop();
	push();
	translate(0, 0, r);
	cylinder(platter.height / 400, height / 30);
	pop();
	ellipsoid(height / 6, height / 30, height / 6, 48, 16);
	c.setAlpha(40);
	fill(c);
	if (index > 0) cylinder(r, height / 200, 48, 1);
	pop();
}

function mousePressed() {
	if (index == rows) {
		divider = 10;
		index = 0;
		angle = 0;
		timer = 0;
		for (let n of piece) {
			n.al = 60;
		}
		drawNotes();
	}
	userStartAudio();
	frameCount = 0;
	playing = !playing;
}
